def find_changed_pairs(inputs, outputs):
    """Identify which (input, output) pairs actually differ."""
    changed = []
    for i, (inp, outp) in enumerate(zip(inputs, outputs)):
        if inp != outp:
            changed.append((i, inp, outp))
    return changed

def find_minimal_edit(s_in, s_out):
    """Find the minimal edit operation between two strings."""
    # Simple implementation for our case
    if len(s_in) < len(s_out):
        # Insertion case
        for i in range(len(s_in)):
            if s_in[i] != s_out[i]:
                return (s_in[i], s_out[i], i)
        return (s_in[-1], s_out[-1], len(s_in)-1) if len(s_in) > 0 else (None, s_out[0], 0)
    elif len(s_in) > len(s_out):
        # Deletion case
        for i in range(len(s_out)):
            if s_in[i] != s_out[i]:
                return (s_in[i], '', i)
        return (s_in[len(s_out)], '', len(s_out))
    else:
        # Substitution case
        for i in range(len(s_in)):
            if s_in[i] != s_out[i]:
                return (s_in[i], s_out[i], i)
        return (None, None, -1)

def propose_rule_candidates(s_in, s_out):
    """Propose candidate replacement rules."""
    # Based on minimal edit, generate candidates
    old_sub, new_sub, pos = find_minimal_edit(s_in, s_out)

    candidates = []

    # If insertion, we want to insert a character
    if len(s_in) < len(s_out):
        # Insert 'j' at position 1 in 'zbfgw' to get 'zjbfgw'
        candidates.append((s_in[pos:pos+1], new_sub))  # This is tricky, let me think differently

    # If substitution, we want to replace one character with another
    elif len(s_in) == len(s_out) and old_sub is not None:
        candidates.append((old_sub, new_sub))

    # For the case where we're replacing substring
    if s_in == 'ghy' and s_out == 'ghzvf':
        # Replace 'hy' with 'zvf'
        candidates.append(('hy', 'zvf'))
    elif s_in == 'cba' and s_out == 'cjba':
        # Replace 'b' with 'j' 
        candidates.append(('b', 'j'))

    # General approach - try to make rules as specific as possible
    return candidates

